select m.name as brand,t.model_family,t.frequency_basis,t.interval_months,t.meter_interval,count(s.id) as steps from public.bf_med_master_pm_templates t join public.bf_med_manufacturers m on m.id=t.manufacturer_id join public.bf_med_master_pm_steps s on s.template_id=t.id where t.reference like 'OEM-20261110%' group by m.name,t.model_family,t.frequency_basis,t.interval_months,t.meter_interval order by m.name,t.model_family;
